model=function(){return `<div class="legend"><span class="entityKey">Сущность: узнаём по номеру</span><span class="valueKey">Значение: сравниваем содержимое</span><span>Рамка: меняем через расписание</span></div><svg class="model" viewBox="0 0 1200 540" role="img" aria-label="Расписание контролирует брони. Бронь содержит временной интервал."><defs><marker id="modelArrow" markerWidth="9" markerHeight="9" refX="8" refY="4.5" orient="auto"><path d="M0 0L9 4.5L0 9" fill="#3159cf"/></marker></defs><g class="node ${modelStep<1?'mutedNode':''}"><rect x="270" y="15" width="900" height="500" rx="26" fill="#edf1ff" stroke="#526cbb" stroke-width="2" stroke-dasharray="10 7"/><text x="305" y="52" class="small">Правила одной комнаты · агрегат</text><rect class="box root" x="505" y="80" width="420" height="125" rx="18"/><text class="title" x="530" y="118">RoomSchedule</text><text class="small" x="530" y="153">Расписание · общая версия</text><text class="small" x="530" y="185">Book / Cancel / Reschedule</text></g><g class="node ${modelStep<2?'mutedNode':''}"><path class="link" d="M610 205V250H485V290" marker-end="url(#modelArrow)"/><text class="small" x="340" y="247">проверяет и изменяет</text><rect class="box" x="310" y="290" width="380" height="170" rx="18"/><text class="title" x="335" y="330">Booking · бронь</text><text class="small" x="335" y="367">ID · организатор · статус</text><text class="small" x="335" y="403">Проверяет отмену и перенос</text><text class="small" x="335" y="437">Закрытый сеттер статуса</text></g><g class="node ${modelStep<3?'mutedNode':''}"><rect class="box" x="15" y="85" width="230" height="140" rx="18"/><text class="title" x="35" y="125">Room</text><text class="small" x="35" y="162">ID · название</text><text class="small" x="35" y="198">Вместимость</text><path class="link" d="M505 142H245" marker-end="url(#modelArrow)"/><text class="small" x="285" y="128">для комнаты</text></g><g class="node ${modelStep<4?'mutedNode':''}"><path class="link" d="M690 370H755" marker-end="url(#modelArrow)"/><text class="small" x="702" y="352">имеет</text><rect class="box vo" x="775" y="305" width="350" height="140" rx="18"/><text class="title" x="795" y="342">TimeInterval</text><text class="small" x="795" y="380">Начало &lt; конец</text><text class="small" x="795" y="417">Проверяет пересечение</text></g></svg>`};
function companiesHtml(){return head('DDD встречается в рабочих системах','Примеры из инженерных статей.')+`<div class="production"><section class="company"><h2>Uber</h2><span class="stamp">Инженерный разбор · 2020</span><div class="domainPods"><div class="pod">Карта<small>поиск места</small></div><div class="pod">Цена<small>расчёт тарифа</small></div><div class="pod">Водитель<small>подбор пары</small></div></div><p>Связанные сервисы объединяют в области. У каждой — понятная точка входа.</p><p class="sourceLine"><a href="https://www.uber.com/us/en/blog/microservice-architecture/" target="_blank" rel="noopener">Uber: DOMA опирается на DDD и другие подходы</a></p></section><section class="company"><h2>Shopify</h2><span class="stamp">Разбор · 2019, ретроспектива · 2024</span><div class="domainPods"><div class="pod sh">Заказы</div><div class="pod sh">Доставка</div><div class="pod sh">Товары</div></div><div class="mapbox core">Модули внутри одного приложения</div><p>Границы помогают менять части системы. Их выбирают с учётом зависимостей кода.</p><p class="sourceLine"><a href="https://shopify.engineering/deconstructing-monolith-designing-software-maximizes-developer-productivity" target="_blank" rel="noopener">Shopify: модульный монолит</a></p></section></div>`+`<div class="mapbox core">В работе: уточняем правило → меняем модель → проверяем тестами</div>`+prompt('Нужен ли отдельный микросервис для каждого нашего класса?')}
function dependenciesHtml(){return head('Зависимости кода: кто о ком знает','Стрелка показывает зависимость кода. Это не движение запроса.')+`<div class="sheet"><svg class="depDiagram" viewBox="0 0 1200 490" role="img" aria-label="UI зависит от Application. Application зависит от Domain. Infrastructure реализует контракт Domain. Domain не знает о базе и экране."><defs><marker id="depArrow" markerWidth="9" markerHeight="9" refX="8" refY="4.5" orient="auto"><path d="M0 0L9 4.5L0 9" style="fill:#3159cf;stroke:none"/></marker></defs><rect class="box" x="25" y="60" width="240" height="130" rx="18"/><text class="title" x="50" y="102">UI</text><text x="50" y="143">Экран / бот</text><path d="M265 122H405" marker-end="url(#depArrow)"/><text x="275" y="101">вызывает</text><rect class="box" x="425" y="60" width="310" height="130" rx="18"/><text class="title" x="450" y="102">Application</text><text x="450" y="143">Создать бронь</text><path d="M735 122H835" marker-end="url(#depArrow)"/><text x="750" y="101">типы</text><rect class="box core" x="855" y="60" width="320" height="240" rx="18"/><text class="title" x="880" y="102">Domain</text><text x="880" y="147">Расписание и бронь</text><text x="880" y="187">Правила</text><text x="880" y="227">Контракт сохранения</text><text x="880" y="267">Без EF Core и Telegram</text><rect class="box" x="425" y="350" width="310" height="120" rx="18"/><text class="title" x="450" y="393">Infrastructure</text><text x="450" y="434">Конкретная база</text><path class="dotted" d="M735 410H1010V315" marker-end="url(#depArrow)"/><text x="770" y="391">реализует контракт</text><text x="30" y="295">Сплошная: использует код</text><text x="30" y="331">Пунктир: реализует контракт</text></svg></div>`+prompt('Как сменить базу, не переписывая Booking и TimeInterval?')}